// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address logAddr) public {
        // Initialize the contract: from then on SetLogFile must be permanently locked.
        c.Initialized();

        // Any attempt to change the log file after initialization must revert.
        bool ok;
        try c.SetLogFile(logAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "SetLogFile must revert after initialization");
    }
}
